#!/usr/bin/env bash
set -Eeuo pipefail

# HYPER-HOST CS16 v3.23 — COHERENT RUNTIME GUARD
#
# Requires installed v3.20 + v3.22 controller.
# Prevents cstrike-only legacy runtimes from being mixed with an unrelated
# modern HLDS engine. Full server-root archives that carry their own hlds_linux
# remain eligible for exact runtime preservation.

SID="${1:-20}"
LIVE_CTL="${HYPER_CTL:-/usr/local/sbin/hyper-cs16-ctl}"
REPO="${HYPER_REPO:-$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)}"
REPO_CTL="$REPO/cs16-panel/bin/hyper-cs16-ctl"
DOMAIN="www.avito.hyper-host.pw"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="/root/hyper-cs16-v3.23-backup-${STAMP}"
LOG="/root/hyper-cs16-v3.23-${STAMP}.log"

mkdir -p "$BACKUP"
exec > >(tee -a "$LOG") 2>&1

die() {
  echo
  echo "[ERROR] $*"
  echo "[ERROR] Log: $LOG"
  echo "[ERROR] Backup: $BACKUP"
  exit 1
}

backup_file() {
  local f="$1"
  [[ -f "$f" ]] || return 0
  local safe
  safe="$(printf '%s' "$f" | sed 's#^/##;s#/#__#g')"
  cp -a "$f" "$BACKUP/$safe"
}

echo "============================================================"
echo " HYPER-HOST CS16 v3.23 — COHERENT RUNTIME GUARD"
echo "============================================================"
echo "Server:     $SID"
echo "Live ctl:   $LIVE_CTL"
echo "Repo:       $REPO"
echo "Backup:     $BACKUP"
echo "Log:        $LOG"
echo

[[ "$SID" =~ ^[0-9]+$ ]] || die "Invalid server id: $SID"
[[ -f "$LIVE_CTL" ]] || die "Live controller not found: $LIVE_CTL"
[[ -f "$REPO_CTL" ]] || die "Repository controller not found: $REPO_CTL"
grep -q "def _v320_prepare_runtime" "$LIVE_CTL" || die "v3.20 adaptive runtime is not installed"
grep -q "def _v322_skip_missing_optional_refs" "$LIVE_CTL" || die "v3.22 optional-file sanitizer is not installed"

PATCHER="$(mktemp /tmp/hh-v323.XXXXXX.py)"
ROOTS="$(mktemp /tmp/hh-v323-roots.XXXXXX)"
NGTMP="$(mktemp /tmp/hh-v323-nginx.XXXXXX)"
trap 'rm -f "$PATCHER" "$ROOTS" "$NGTMP" 2>/dev/null || true' EXIT
printf '%s' '' | base64 -d >"$PATCHER"
python3 -m py_compile "$PATCHER" || die "Embedded v3.23 patcher is invalid"

echo "[1/8] Backing up controller and panel..."
backup_file "$LIVE_CTL"
backup_file "$REPO_CTL"

echo
echo "[2/8] Patching LIVE controller..."
python3 "$PATCHER" ctl "$LIVE_CTL" || die "Live controller patch failed"
python3 -m py_compile "$LIVE_CTL" || die "Live controller syntax validation failed"
echo "[OK] live controller patched"

echo
echo "[3/8] Synchronizing verified controller into current repo checkout..."
install -m 0755 "$LIVE_CTL" "$REPO_CTL"
python3 -m py_compile "$REPO_CTL" || die "Repository controller validation failed"

echo
echo "[4/8] Patching active panel message..."
for root in   "/var/www/hyper-host-sites/$DOMAIN/public_html"   "/var/www/$DOMAIN/public_html"   "/var/www/$DOMAIN"
do
  [[ -f "$root/index.php" ]] && echo "$root" >>"$ROOTS"
done

if command -v nginx >/dev/null 2>&1; then
  nginx -T >"$NGTMP" 2>&1 || true
  python3 - "$NGTMP" "$DOMAIN" >>"$ROOTS" <<'PYROOTS'
import re,sys
text=open(sys.argv[1],encoding='utf-8',errors='ignore').read()
domain=sys.argv[2]
for block in re.findall(r'server\s*\{.*?\n\}',text,re.S):
    if domain not in block: continue
    for root in re.findall(r'(?m)^\s*root\s+([^;]+);',block):
        root=root.strip()
        if root.startswith('/'): print(root)
PYROOTS
fi

while IFS= read -r idx; do
  grep -q "serverTabs" "$idx" 2>/dev/null || continue
  echo "$(dirname "$idx")" >>"$ROOTS"
done < <(find /var/www -xdev -type f -name index.php 2>/dev/null || true)

sort -u "$ROOTS" -o "$ROOTS"
PANEL_COUNT=0
FIRST_ROOT=""
while IFS= read -r DOCROOT; do
  [[ -n "$DOCROOT" ]] || continue
  [[ -f "$DOCROOT/index.php" ]] || continue
  grep -q "serverTabs" "$DOCROOT/index.php" || continue
  PANEL_COUNT=$((PANEL_COUNT+1))
  [[ -n "$FIRST_ROOT" ]] || FIRST_ROOT="$DOCROOT"
  backup_file "$DOCROOT/index.php"
  python3 "$PATCHER" index "$DOCROOT/index.php" || die "Panel patch failed: $DOCROOT"
  php -l "$DOCROOT/index.php" >/dev/null || die "PHP syntax error: $DOCROOT/index.php"
  echo "[PATCHED PANEL] $DOCROOT"
done <"$ROOTS"

if [[ "$PANEL_COUNT" -gt 0 && -n "$FIRST_ROOT" ]]; then
  install -m 0644 "$FIRST_ROOT/index.php" "$REPO/cs16-panel/public/index.php"
  php -l "$REPO/cs16-panel/public/index.php" >/dev/null || die "Repo panel validation failed"
else
  echo "[WARN] Active CS16 panel root not found; backend is patched, panel wording unchanged."
fi

while IFS= read -r svc; do
  [[ -n "$svc" ]] || continue
  systemctl reload "$svc" 2>/dev/null || systemctl restart "$svc" 2>/dev/null || true
done < <(systemctl list-units --type=service --state=running --no-legend 2>/dev/null | awk '/php.*fpm/ {print $1}')

echo
echo "[5/8] Verifying future-import guard..."
python3 - "$LIVE_CTL" <<'PYVERIFY'
from pathlib import Path
import ast,sys
s=Path(sys.argv[1]).read_text(encoding='utf-8',errors='surrogateescape')
ast.parse(s)
checks={
 'v3.23 helper':'def _v323_analyze_archive_runtime' in s,
 'archive runtime scope':'runtime_scope=_v323_analyze_archive_runtime(payload,layout)' in s,
 'coherent prepare':'runtime_coherence=_v323_prepare_coherent_runtime(stage,c,runtime_scope)' in s,
 'import marker':'+coherent-runtime-v323' in s,
 'current repair command':'def runtime_coherent_apply(sid:int):' in s,
}
bad=[]
for name,ok in checks.items():
    print(('[OK] ' if ok else '[FAIL] ')+name)
    if not ok: bad.append(name)
if bad: raise SystemExit('[ERROR] verification failed: '+', '.join(bad))
PYVERIFY

echo
echo "[6/8] Applying coherent runtime to CURRENT server #$SID..."
set +e
CURRENT_OUT="$($LIVE_CTL runtime-coherent-apply "$SID" 2>&1)"
CURRENT_RC=$?
set -e
echo "$CURRENT_OUT"
if [[ "$CURRENT_RC" -ne 0 ]]; then
  echo "[WARN] v3.23 architecture IS installed, but current-server coherent repair returned non-zero."
  echo "[WARN] The runtime helper restores its runtime backup on failure."
else
  echo "[OK] current server coherent runtime applied"
fi

echo
echo "[7/8] Runtime status after repair..."
$LIVE_CTL runtime-status "$SID" 2>&1 || true
echo "--- version ---"
$LIVE_CTL rcon "$SID" "version" 2>&1 || true
echo "--- meta list ---"
$LIVE_CTL rcon "$SID" "meta list" 2>&1 || true
echo "--- amxx plugins ---"
$LIVE_CTL rcon "$SID" "amxx plugins" 2>&1 || true

echo
echo "[8/8] Controller idempotence check..."
python3 "$PATCHER" ctl "$LIVE_CTL" || die "Repeated v3.23 controller patch failed"
python3 -m py_compile "$LIVE_CTL" || die "Controller invalid after repeated patch"
install -m 0755 "$LIVE_CTL" "$REPO_CTL"
echo "[OK] repeated patch pass is valid"

echo
echo "============================================================"
echo " v3.23 INSTALLED SUCCESSFULLY"
echo "============================================================"
echo "Future import rule:"
echo " - FULL server-root + own hlds_linux -> archive runtime may be preserved"
echo " - cstrike runtime WITHOUT matching hlds_linux -> NEVER mixed with host engine"
echo " - partial runtime -> ReHLDS/ReGameDLL + Metamod-R + managed AMXX runtime"
echo " - gameplay plugins/configs/models/maps/sounds stay from the assembly"
echo " - legacy Reunion/dproto loader from partial runtime is disabled"
echo " - import gets +coherent-runtime-v323"
echo
echo "Backup: $BACKUP"
echo "Log:    $LOG"
echo "============================================================"
